/// Minimal strict JSON helpers. Content files are generated by `tools/curriculum`;
/// malformed content must fail loudly with a readable path instead of a cast error.
library;

/// Converts a raw JSON value (e.g. an array element) into a string-keyed map.
Map<String, Object?> mapOf(Object? v, String what) {
  if (v is Map<String, Object?>) {
    return v;
  }
  if (v is Map) {
    return v.cast<String, Object?>();
  }
  throw FormatException('$what must be a JSON object, got ${v.runtimeType}');
}

Map<String, Object?> reqMap(Map<String, Object?> m, String key) {
  final v = m[key];
  if (v == null) {
    throw FormatException('"$key" is missing');
  }
  return mapOf(v, '"$key"');
}

Map<String, Object?>? optMap(Map<String, Object?> m, String key) {
  if (m[key] == null) {
    return null;
  }
  return reqMap(m, key);
}

List<Object?> reqList(Map<String, Object?> m, String key) {
  final v = m[key];
  if (v is List<Object?>) {
    return v;
  }
  if (v is List) {
    return v.cast<Object?>();
  }
  throw FormatException('"$key" must be a JSON array, got ${v.runtimeType}');
}

String reqStr(Map<String, Object?> m, String key) {
  final v = m[key];
  if (v is String && v.trim().isNotEmpty) {
    return v;
  }
  throw FormatException('"$key" must be a non-empty string, got ${v.runtimeType}');
}

String? optStr(Map<String, Object?> m, String key) {
  final v = m[key];
  if (v == null) {
    return null;
  }
  if (v is String) {
    return v;
  }
  throw FormatException('"$key" must be a string when present, got ${v.runtimeType}');
}

int reqInt(Map<String, Object?> m, String key) {
  final v = m[key];
  if (v is int) {
    return v;
  }
  throw FormatException('"$key" must be an integer, got ${v.runtimeType}');
}

int optInt(Map<String, Object?> m, String key, int fallback) {
  final v = m[key];
  if (v == null) {
    return fallback;
  }
  if (v is int) {
    return v;
  }
  throw FormatException('"$key" must be an integer when present, got ${v.runtimeType}');
}

double reqDouble(Map<String, Object?> m, String key) {
  final v = m[key];
  if (v is num) {
    return v.toDouble();
  }
  throw FormatException('"$key" must be a number, got ${v.runtimeType}');
}

double optDouble(Map<String, Object?> m, String key, double fallback) {
  final v = m[key];
  if (v == null) {
    return fallback;
  }
  if (v is num) {
    return v.toDouble();
  }
  throw FormatException('"$key" must be a number when present, got ${v.runtimeType}');
}
